-- Read-only independent verification. Execute AFTER the full July staff/vacancy/timing guarded correction reports PASS.
WITH ctx AS MATERIALIZED(SELECT set_config('app.current_company_id','1',true) cid),v AS MATERIALIZED(SELECT id,voucher_date FROM vouchers WHERE company_id=(SELECT cid::int FROM ctx) AND deleted_at IS NULL AND optional=false),e AS MATERIALIZED(SELECT id,voucher_id,ledger_account_id,debit_amount,credit_amount FROM voucher_entries WHERE company_id=(SELECT cid::int FROM ctx) AND voucher_id IN(SELECT id FROM v)),s AS MATERIALIZED(SELECT e.ledger_account_id,SUM(e.debit_amount-e.credit_amount) balance_dr FROM e WHERE e.ledger_account_id IN(881,1007,1021,1022,4282) GROUP BY e.ledger_account_id),monthly AS MATERIALIZED(SELECT EXTRACT(MONTH FROM v.voucher_date)::int mo,COALESCE(SUM(e.debit_amount),0) dr,COALESCE(SUM(e.credit_amount),0) cr FROM e JOIN v ON v.id=e.voucher_id WHERE e.ledger_account_id=1007 AND v.voucher_date>=DATE '2026-01-01' AND v.voucher_date<DATE '2026-12-01' GROUP BY 1),expected(mo,target) AS(VALUES(1,32700::numeric),(2,34450),(3,34450),(4,37950),(5,40950),(6,40950),(7,41250),(8,43250),(9,43250),(10,46200),(11,38950)),result AS MATERIALIZED(SELECT (SELECT dr FROM monthly WHERE mo=6) june_dr,(SELECT cr FROM monthly WHERE mo=6) june_cr,(SELECT dr FROM monthly WHERE mo=7) july_dr,(SELECT cr FROM monthly WHERE mo=7) july_cr,(SELECT dr FROM monthly WHERE mo=10) october_dr,(SELECT cr FROM monthly WHERE mo=10) october_cr,COALESCE((SELECT balance_dr FROM s WHERE ledger_account_id=1007),0) expense_balance_dr,COALESCE((SELECT balance_dr FROM s WHERE ledger_account_id=881),0) retired_881_balance,COALESCE((SELECT balance_dr FROM s WHERE ledger_account_id=1021),0) payable_balance_dr,COALESCE((SELECT balance_dr FROM s WHERE ledger_account_id=1022),0) prepaid_balance_dr,COALESCE((SELECT balance_dr FROM s WHERE ledger_account_id=4282),0) timing_balance_dr,(SELECT COUNT(*) FROM expected x JOIN monthly m ON m.mo=x.mo WHERE m.dr-m.cr=x.target) months_matching_target,(SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id IN(15659,17518,17519,17520) AND deleted_at IS NOT NULL) superseded_journals,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=33996) invalid_staff_entry_remaining,(SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=9919 AND total_amount=13950 AND deleted_at IS NULL) july_header_correct,(SELECT COUNT(*) FROM property_monthly_ledger WHERE company_id=1 AND id=617968 AND contract_id=26 AND year=2026 AND month=7 AND expected_amount=0 AND paid_amount=0 AND accrual_voucher_id IS NULL) july_staff_not_due,(SELECT COUNT(*) FROM property_contracts WHERE company_id=1 AND id=26 AND status='ENDED' AND end_date=DATE '2026-06-30') staff_contract_correct,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id IN(32703,33088) AND ledger_account_id=1022 AND debit_amount IN(1000,600)) june_advance_sources,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=9919 AND ledger_account_id=1007 AND debit_amount=1600 AND credit_amount=0) july_rent_recognized,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=9919 AND ledger_account_id=1022 AND credit_amount=1600 AND debit_amount=0) july_prepaid_used,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id IN(32704,33089) AND ledger_account_id=6 AND credit_amount IN(1000,600) AND debit_amount=0) cash_counterparts_unchanged,(SELECT COUNT(*) FROM audit_log WHERE company_id=1 AND user_id='system:hadi-jul-vacated-staff-full-timing-fix-20261110' AND action='repair') repair_audits)SELECT CASE WHEN june_dr=40950 AND june_cr=0 AND july_dr=41250 AND july_cr=0 AND october_dr=46200 AND october_cr=0 AND expense_balance_dr=434350 AND retired_881_balance=0 AND payable_balance_dr=-18000 AND prepaid_balance_dr=7000 AND timing_balance_dr=0 AND months_matching_target=11 AND superseded_journals=4 AND invalid_staff_entry_remaining=0 AND july_header_correct=1 AND july_staff_not_due=1 AND staff_contract_correct=1 AND june_advance_sources=2 AND july_rent_recognized=1 AND july_prepaid_used=1 AND cash_counterparts_unchanged=2 AND repair_audits=10 THEN 'PASS HADI JULY STAFF AND TIMING COMPLETE' ELSE 'NOT APPLIED / FAILED - DO NOT RUN NEW CORRECTIONS' END verification,result.* FROM result;
